SELECT YEAR(stores.opened_date) AS opened_year, stores.city, COUNT(DISTINCT store_sales.units) AS unique_products, AVG(store_sales.units) AS avg_units FROM store_sales INNER JOIN stores ON stores.id = store_sales.store_id RIGHT JOIN products ON products.id = store_sales.product_id WHERE products.stock_qty > 151 GROUP BY YEAR(stores.opened_date), stores.city ORDER BY 4 DESC, stores.city DESC
